INSERT INTO public.questions (category_id, texts, question_type, have_answers, answers, order_index)
VALUES
('daily_love_language', '{"text_en": "What makes you feel most loved?", "text_tr": "Seni en çok ne sevildiğini hissettirir?", "text_es": "¿Qué te hace sentir más querido/a?", "text_pt": "O que mais te faz se sentir amado(a)?"}'::jsonb, 'choice', true, '{"answers_en": ["Hearing it said out loud", "Undivided time together", "Them making my life easier", "Physical touch", "A thoughtful surprise"], "answers_tr": ["Bunu açıkça duymak", "Bölünmeden birlikte geçen zaman", "Hayatımı kolaylaştırması", "Fiziksel temas", "Düşünülmüş bir sürpriz"], "answers_es": ["Oírlo en voz alta", "Tiempo juntos sin distracciones", "Que me haga la vida más fácil", "El contacto físico", "Una sorpresa pensada"], "answers_pt": ["Ouvir isso em voz alta", "Tempo juntos sem distrações", "Que facilite minha vida", "Toque físico", "Uma surpresa pensada"]}'::jsonb, 1),
('daily_love_language', '{"text_en": "How do you most naturally show love?", "text_tr": "Sevgini en doğal hâlinle nasıl gösterirsin?", "text_es": "¿Cómo demuestras amor de forma más natural?", "text_pt": "Como você demonstra amor de forma mais natural?"}'::jsonb, 'choice', true, '{"answers_en": ["By saying it", "By making time", "By doing things for them", "Through touch", "With small surprises"], "answers_tr": ["Söyleyerek", "Vakit ayırarak", "Onun için bir şeyler yaparak", "Dokunarak", "Küçük sürprizlerle"], "answers_es": ["Diciéndolo", "Dedicando tiempo", "Haciendo cosas por mi pareja", "Con el contacto", "Con pequeñas sorpresas"], "answers_pt": ["Dizendo", "Reservando tempo", "Fazendo coisas pelo parceiro", "Com toque", "Com pequenas surpresas"]}'::jsonb, 2),
('daily_love_language', '{"text_en": "What makes you feel unloved the fastest?", "text_tr": "Seni en hızlı ne sevilmediğini hissettirir?", "text_es": "¿Qué te hace sentir poco querido/a más rápido?", "text_pt": "O que mais rápido te faz se sentir pouco amado(a)?"}'::jsonb, 'choice', true, '{"answers_en": ["Days without a kind word", "Them on their phone when we''re together", "Being left to handle everything", "No affection for a while", "My effort going unnoticed"], "answers_tr": ["Günlerce tek bir güzel söz duymamak", "Birlikteyken onun telefonda olması", "Her şeyle tek başıma uğraşmak", "Bir süre hiç sevgi gösterilmemesi", "Emeğimin fark edilmemesi"], "answers_es": ["Días sin una palabra amable", "Que esté con el móvil cuando estamos juntos", "Tener que encargarme de todo", "Pasar un tiempo sin cariño", "Que mi esfuerzo pase desapercibido"], "answers_pt": ["Dias sem uma palavra gentil", "Ele no celular quando estamos juntos", "Ter que dar conta de tudo sozinho(a)", "Um tempo sem carinho", "Meu esforço passar despercebido"]}'::jsonb, 3),
('daily_love_language', '{"text_en": "When you''re stressed, what do you want from your partner?", "text_tr": "Stresliyken partnerinden ne istersin?", "text_es": "Cuando estás estresado/a, ¿qué quieres de tu pareja?", "text_pt": "Quando está estressado(a), o que você quer do parceiro?"}'::jsonb, 'choice', true, '{"answers_en": ["Talk it through with me", "Just be next to me", "Take something off my plate", "Hold me", "Give me space"], "answers_tr": ["Benimle konuşsun", "Sadece yanımda olsun", "Bir işimi üstlensin", "Bana sarılsın", "Bana alan tanısın"], "answers_es": ["Que lo hable conmigo", "Que solo esté a mi lado", "Que se encargue de algo por mí", "Que me abrace", "Que me dé espacio"], "answers_pt": ["Que converse comigo", "Que só fique do meu lado", "Que assuma alguma tarefa", "Que me abrace", "Que me dê espaço"]}'::jsonb, 4),
('daily_love_language', '{"text_en": "How much physical affection do you want on a normal day?", "text_tr": "Sıradan bir günde ne kadar fiziksel yakınlık istersin?", "text_es": "¿Cuánto afecto físico quieres en un día normal?", "text_pt": "Quanto carinho físico você quer num dia normal?"}'::jsonb, 'choice', true, '{"answers_en": ["A lot, all the time", "Several moments a day", "A little is enough", "I''m not very physical"], "answers_tr": ["Çok, sürekli", "Gün içinde birkaç kez", "Biraz yeterli", "Pek fiziksel biri değilim"], "answers_es": ["Mucho, todo el tiempo", "Varios momentos al día", "Un poco es suficiente", "No soy muy físico/a"], "answers_pt": ["Muito, o tempo todo", "Vários momentos no dia", "Um pouco basta", "Não sou muito de contato"]}'::jsonb, 5),
('daily_love_language', '{"text_en": "How often do you feel your love goes unnoticed?", "text_tr": "Gösterdiğin sevginin ne sıklıkla fark edilmediğini hissediyorsun?", "text_es": "¿Con qué frecuencia sientes que tu amor pasa desapercibido?", "text_pt": "Com que frequência você sente que seu amor passa despercebido?"}'::jsonb, 'choice', true, '{"answers_en": ["Almost never", "Sometimes", "Often", "Most of the time"], "answers_tr": ["Neredeyse hiç", "Bazen", "Sık sık", "Çoğu zaman"], "answers_es": ["Casi nunca", "A veces", "A menudo", "Casi siempre"], "answers_pt": ["Quase nunca", "Às vezes", "Com frequência", "Na maior parte do tempo"]}'::jsonb, 6),
('daily_love_language', '{"text_en": "Describe the last moment you felt truly loved by your partner.", "text_tr": "Partnerin tarafından gerçekten sevildiğini hissettiğin son anı anlat.", "text_es": "Describe el último momento en que te sentiste de verdad querido/a por tu pareja.", "text_pt": "Descreva o último momento em que você se sentiu de verdade amado(a) pelo parceiro."}'::jsonb, 'text', false, NULL, 7),
('daily_love_language', '{"text_en": "What do you do to show love that you think your partner doesn''t notice?", "text_tr": "Sevgini göstermek için yaptığın ama partnerinin fark etmediğini düşündüğün şey ne?", "text_es": "¿Qué haces para demostrar amor que crees que tu pareja no nota?", "text_pt": "O que você faz para demonstrar amor que acha que seu parceiro não percebe?"}'::jsonb, 'text', false, NULL, 8),
('daily_conflict', '{"text_en": "When a disagreement starts, your first instinct is to…", "text_tr": "Bir anlaşmazlık başladığında ilk içgüdün…", "text_es": "Cuando empieza un desacuerdo, tu primer instinto es…", "text_pt": "Quando começa um desentendimento, seu primeiro instinto é…"}'::jsonb, 'choice', true, '{"answers_en": ["Say everything right away", "Go quiet and pull back", "Smooth it over, even if I''m not done", "Leave the room to cool off"], "answers_tr": ["Her şeyi hemen söylemek", "Susup geri çekilmek", "İçim rahat etmese de ortamı yumuşatmak", "Sakinleşmek için odadan çıkmak"], "answers_es": ["Decirlo todo de inmediato", "Callarme y alejarme", "Suavizarlo, aunque no haya terminado", "Salir de la habitación para calmarme"], "answers_pt": ["Falar tudo na hora", "Ficar quieto(a) e me afastar", "Apaziguar, mesmo sem ter terminado", "Sair do cômodo para esfriar a cabeça"]}'::jsonb, 1),
('daily_conflict', '{"text_en": "What do you need before a fight can really end for you?", "text_tr": "Bir kavganın senin için gerçekten bitmesi için neye ihtiyacın var?", "text_es": "¿Qué necesitas para que una pelea termine de verdad para ti?", "text_pt": "Do que você precisa para uma briga terminar de verdade pra você?"}'::jsonb, 'choice', true, '{"answers_en": ["A sincere apology", "To feel understood", "A clear solution", "Time alone first", "Physical closeness"], "answers_tr": ["Samimi bir özür", "Anlaşıldığımı hissetmek", "Net bir çözüm", "Önce biraz yalnız kalmak", "Fiziksel yakınlık"], "answers_es": ["Una disculpa sincera", "Sentirme comprendido/a", "Una solución clara", "Primero un rato a solas", "Cercanía física"], "answers_pt": ["Um pedido de desculpas sincero", "Me sentir compreendido(a)", "Uma solução clara", "Um tempo sozinho(a) antes", "Proximidade física"]}'::jsonb, 2),
('daily_conflict', '{"text_en": "How do you feel about making the first move to make up?", "text_tr": "Barışmak için ilk adımı atmak hakkında ne hissediyorsun?", "text_es": "¿Qué sientes respecto a dar el primer paso para reconciliarse?", "text_pt": "O que você sente sobre dar o primeiro passo para fazer as pazes?"}'::jsonb, 'choice', true, '{"answers_en": ["I usually do it and I''m fine with that", "I usually do it and it''s starting to bother me", "I tend to wait for them", "It''s hard for me, even when I want to"], "answers_tr": ["Genelde ben atarım, sorun değil", "Genelde ben atarım ve bu artık canımı sıkıyor", "Genelde onun gelmesini beklerim", "İstesem bile bu bana zor geliyor"], "answers_es": ["Suelo darlo yo y me parece bien", "Suelo darlo yo y empieza a molestarme", "Tiendo a esperar a que lo dé mi pareja", "Me cuesta, aunque quiera"], "answers_pt": ["Costumo dar e tudo bem", "Costumo dar e isso está começando a me incomodar", "Costumo esperar o parceiro", "É difícil pra mim, mesmo querendo"]}'::jsonb, 3),
('daily_conflict', '{"text_en": "After a fight is over, how long does it stay with you?", "text_tr": "Bir kavga bittikten sonra ne kadar aklında kalır?", "text_es": "Después de una pelea, ¿cuánto tiempo te dura?", "text_pt": "Depois que a briga acaba, quanto tempo ela fica com você?"}'::jsonb, 'choice', true, '{"answers_en": ["It''s gone once we make up", "A few hours", "A day or two", "It comes back up later"], "answers_tr": ["Barıştığımız an biter", "Birkaç saat", "Bir iki gün", "Sonra tekrar aklıma gelir"], "answers_es": ["Se me pasa al reconciliarnos", "Unas horas", "Uno o dos días", "Vuelve a salir más adelante"], "answers_pt": ["Passa quando fazemos as pazes", "Algumas horas", "Um ou dois dias", "Volta a aparecer depois"]}'::jsonb, 4),
('daily_conflict', '{"text_en": "What escalates a fight fastest for you?", "text_tr": "Bir kavgayı senin için en hızlı ne büyütür?", "text_es": "¿Qué hace que una pelea escale más rápido para ti?", "text_pt": "O que mais rápido faz uma briga piorar pra você?"}'::jsonb, 'choice', true, '{"answers_en": ["A raised voice or harsh tone", "Being interrupted or not heard", "Old issues being brought up", "Silence or walking away", "Sarcasm or eye-rolling"], "answers_tr": ["Yükselen ses ya da sert ton", "Sözümün kesilmesi, dinlenmemek", "Eski meselelerin açılması", "Susmak ya da çekip gitmek", "İğneleme ya da göz devirme"], "answers_es": ["Levantar la voz o un tono duro", "Que me interrumpan o no me escuchen", "Que saquen temas viejos", "El silencio o irse", "El sarcasmo o poner los ojos en blanco"], "answers_pt": ["Voz alta ou tom duro", "Ser interrompido(a) ou não ser ouvido(a)", "Trazer problemas antigos à tona", "Silêncio ou ir embora", "Sarcasmo ou revirar os olhos"]}'::jsonb, 5),
('daily_conflict', '{"text_en": "What do you hold back to keep the peace?", "text_tr": "Ortam bozulmasın diye neleri söylemezsin?", "text_es": "¿Qué te callas para mantener la paz?", "text_pt": "O que você guarda pra si para manter a paz?"}'::jsonb, 'choice', true, '{"answers_en": ["Nothing, I say what bothers me", "Small annoyances", "Bigger needs I have", "Things about their family or friends"], "answers_tr": ["Hiçbir şey, canımı sıkanı söylerim", "Küçük rahatsızlıklarımı", "Daha büyük ihtiyaçlarımı", "Ailesi ya da arkadaşlarıyla ilgili şeyleri"], "answers_es": ["Nada, digo lo que me molesta", "Pequeñas molestias", "Necesidades más grandes que tengo", "Cosas sobre su familia o amigos"], "answers_pt": ["Nada, falo o que me incomoda", "Pequenos incômodos", "Necessidades maiores que eu tenho", "Coisas sobre a família ou os amigos dele"]}'::jsonb, 6),
('daily_conflict', '{"text_en": "In a few words: what do you two keep arguing about?", "text_tr": "Birkaç kelimeyle: ikiniz sürekli ne hakkında tartışıyorsunuz?", "text_es": "En pocas palabras: ¿sobre qué discuten una y otra vez?", "text_pt": "Em poucas palavras: sobre o que vocês vivem discutindo?"}'::jsonb, 'text', false, NULL, 7),
('daily_conflict', '{"text_en": "What does your partner do in arguments that you wish they''d stop?", "text_tr": "Partnerinin tartışırken yaptığı ve bırakmasını istediğin şey ne?", "text_es": "¿Qué hace tu pareja en las discusiones que te gustaría que dejara de hacer?", "text_pt": "O que seu parceiro faz nas discussões que você gostaria que ele parasse de fazer?"}'::jsonb, 'text', false, NULL, 8),
('daily_everyday_life', '{"text_en": "How fairly do you feel chores are split between you?", "text_tr": "Ev işlerinin aranızda ne kadar adil paylaşıldığını düşünüyorsun?", "text_es": "¿Qué tan justo sientes que se reparten las tareas de casa?", "text_pt": "Quão justa você sente que é a divisão das tarefas de casa?"}'::jsonb, 'choice', true, '{"answers_en": ["Completely fair", "Mostly fair", "I do more than my share", "My partner does more than their share"], "answers_tr": ["Tamamen adil", "Çoğunlukla adil", "Ben payıma düşenden fazlasını yapıyorum", "Partnerim payına düşenden fazlasını yapıyor"], "answers_es": ["Totalmente justo", "Bastante justo", "Yo hago más de lo que me toca", "Mi pareja hace más de lo que le toca"], "answers_pt": ["Totalmente justa", "Quase sempre justa", "Eu faço mais do que a minha parte", "Meu parceiro faz mais do que a parte dele"]}'::jsonb, 1),
('daily_everyday_life', '{"text_en": "How much time alone do you need in a normal week?", "text_tr": "Normal bir haftada ne kadar yalnız zamana ihtiyaç duyarsın?", "text_es": "¿Cuánto tiempo a solas necesitas en una semana normal?", "text_pt": "De quanto tempo sozinho(a) você precisa numa semana normal?"}'::jsonb, 'choice', true, '{"answers_en": ["Almost none", "An hour or two", "An evening or more", "A lot, and I don''t always say it"], "answers_tr": ["Neredeyse hiç", "Bir iki saat", "Bir akşam ya da daha fazla", "Çok, ve bunu hep söylemiyorum"], "answers_es": ["Casi nada", "Una o dos horas", "Una tarde o más", "Mucho, y no siempre lo digo"], "answers_pt": ["Quase nada", "Uma ou duas horas", "Uma noite ou mais", "Muito, e nem sempre eu digo"]}'::jsonb, 2),
('daily_everyday_life', '{"text_en": "Your ideal weekday evening together?", "text_tr": "Birlikte ideal hafta içi akşamınız?", "text_es": "¿Su noche ideal entre semana juntos?", "text_pt": "A noite ideal de vocês num dia de semana?"}'::jsonb, 'choice', true, '{"answers_en": ["Cooking and eating together", "Watching something on the couch", "Going out somewhere", "Side by side, each doing our own thing"], "answers_tr": ["Birlikte yemek yapıp yemek", "Kanepede bir şey izlemek", "Bir yere çıkmak", "Yan yana, herkes kendi işinde"], "answers_es": ["Cocinar y cenar juntos", "Ver algo en el sofá", "Salir a algún sitio", "Uno al lado del otro, cada uno a lo suyo"], "answers_pt": ["Cozinhar e jantar juntos", "Assistir algo no sofá", "Sair para algum lugar", "Lado a lado, cada um na sua"]}'::jsonb, 3),
('daily_everyday_life', '{"text_en": "How do you feel about phones when you''re together?", "text_tr": "Birlikteyken telefonlar hakkında ne düşünüyorsun?", "text_es": "¿Qué piensas de los móviles cuando están juntos?", "text_pt": "O que você acha dos celulares quando vocês estão juntos?"}'::jsonb, 'choice', true, '{"answers_en": ["Not a problem for us", "It bothers me sometimes", "It bothers me a lot", "I''m probably on mine more"], "answers_tr": ["Bizim için sorun değil", "Bazen canımı sıkıyor", "Çok canımı sıkıyor", "Herhalde telefonda daha çok olan benim"], "answers_es": ["No es un problema para nosotros", "A veces me molesta", "Me molesta mucho", "Seguramente yo lo uso más"], "answers_pt": ["Não é problema pra gente", "Às vezes me incomoda", "Me incomoda muito", "Provavelmente eu uso mais"]}'::jsonb, 4),
('daily_everyday_life', '{"text_en": "Weekends should be…", "text_tr": "Hafta sonları…", "text_es": "Los fines de semana deberían ser…", "text_pt": "Os fins de semana deveriam ser…"}'::jsonb, 'choice', true, '{"answers_en": ["Planned and full", "One plan, the rest free", "Totally unplanned", "Mostly rest at home"], "answers_tr": ["Planlı ve dolu olmalı", "Tek bir plan, gerisi serbest olmalı", "Tamamen plansız olmalı", "Çoğunlukla evde dinlenmeli"], "answers_es": ["Planeados y llenos", "Un plan y el resto libre", "Sin ningún plan", "Sobre todo descansar en casa"], "answers_pt": ["Planejados e cheios", "Um plano e o resto livre", "Sem plano nenhum", "Principalmente descanso em casa"]}'::jsonb, 5),
('daily_everyday_life', '{"text_en": "How tidy should home be?", "text_tr": "Ev ne kadar düzenli olmalı?", "text_es": "¿Qué tan ordenada debe estar la casa?", "text_pt": "Quão arrumada a casa deve estar?"}'::jsonb, 'choice', true, '{"answers_en": ["Spotless", "Tidy enough", "Lived-in is cozy", "I don''t notice the mess"], "answers_tr": ["Pırıl pırıl", "Yeterince toplu", "Biraz dağınık daha samimi", "Dağınıklığı fark etmem"], "answers_es": ["Impecable", "Lo bastante ordenada", "Un poco de desorden es acogedor", "No noto el desorden"], "answers_pt": ["Impecável", "Arrumada o suficiente", "Um pouco bagunçada é aconchegante", "Nem percebo a bagunça"]}'::jsonb, 6),
('daily_everyday_life', '{"text_en": "What part of your everyday life together do you love most?", "text_tr": "Birlikte gündelik hayatınızın en çok sevdiğin kısmı ne?", "text_es": "¿Qué parte de su día a día juntos es la que más te gusta?", "text_pt": "Qual parte do dia a dia de vocês você mais ama?"}'::jsonb, 'text', false, NULL, 7),
('daily_everyday_life', '{"text_en": "What small daily thing would you change about how you live together?", "text_tr": "Birlikte yaşayışınızla ilgili değiştirmek istediğin küçük, gündelik bir şey ne?", "text_es": "¿Qué pequeña cosa del día a día cambiarías de cómo viven juntos?", "text_pt": "Que pequena coisa do dia a dia você mudaria em como vocês vivem juntos?"}'::jsonb, 'text', false, NULL, 8),
('daily_trust_jealousy', '{"text_en": "Looking at your partner''s phone is…", "text_tr": "Partnerinin telefonuna bakmak…", "text_es": "Mirar el móvil de tu pareja es…", "text_pt": "Olhar o celular do parceiro é…"}'::jsonb, 'choice', true, '{"answers_en": ["Never okay, it''s private", "Fine with permission", "Fine, we have nothing to hide", "Something I''ve done without asking"], "answers_tr": ["Asla olmaz, özeldir", "İzinle olur", "Olur, saklayacak bir şeyimiz yok", "Sormadan yaptığım bir şey"], "answers_es": ["Nunca está bien, es privado", "Está bien con permiso", "Está bien, no tenemos nada que ocultar", "Algo que he hecho sin preguntar"], "answers_pt": ["Nunca é ok, é privado", "Ok com permissão", "Ok, não temos nada a esconder", "Algo que já fiz sem perguntar"]}'::jsonb, 1),
('daily_trust_jealousy', '{"text_en": "Someone gives your partner a lot of attention. You…", "text_tr": "Biri partnerine çok ilgi gösteriyor. Sen…", "text_es": "Alguien le presta mucha atención a tu pareja. Tú…", "text_pt": "Alguém dá muita atenção ao seu parceiro. Você…"}'::jsonb, 'choice', true, '{"answers_en": ["Don''t mind at all", "Feel a small sting but trust them", "Would want to talk about it", "Would get openly jealous"], "answers_tr": ["Hiç umursamam", "Hafif bir sızı hissederim ama güvenirim", "Bunu konuşmak isterim", "Açıkça kıskanırım"], "answers_es": ["No me importa en absoluto", "Siento una punzada, pero confío", "Querría hablarlo", "Me pondría celoso/a abiertamente"], "answers_pt": ["Não ligo nem um pouco", "Sinto uma pontinha, mas confio", "Ia querer conversar", "Ficaria com ciúme abertamente"]}'::jsonb, 2),
('daily_trust_jealousy', '{"text_en": "Your partner staying friends with an ex is…", "text_tr": "Partnerinin eski sevgilisiyle arkadaş kalması…", "text_es": "Que tu pareja siga siendo amiga de su ex es…", "text_pt": "Seu parceiro continuar amigo de um ex é…"}'::jsonb, 'choice', true, '{"answers_en": ["Totally fine", "Fine if there''s nothing left", "Uncomfortable for me", "A dealbreaker"], "answers_tr": ["Tamamen normal", "Aralarında bir şey kalmadıysa sorun değil", "Beni rahatsız eder", "Kabul edilemez"], "answers_es": ["Totalmente normal", "Bien si no queda nada", "Me incomoda", "Inaceptable"], "answers_pt": ["Totalmente normal", "Ok se não sobrou nada", "Me incomoda", "Inaceitável"]}'::jsonb, 3),
('daily_trust_jealousy', '{"text_en": "How often do you feel jealous, even if you don''t show it?", "text_tr": "Göstermesen bile ne sıklıkla kıskançlık hissediyorsun?", "text_es": "¿Con qué frecuencia sientes celos, aunque no lo muestres?", "text_pt": "Com que frequência você sente ciúme, mesmo sem demonstrar?"}'::jsonb, 'choice', true, '{"answers_en": ["Often", "Sometimes", "Rarely", "Never"], "answers_tr": ["Sık sık", "Bazen", "Nadiren", "Hiç"], "answers_es": ["A menudo", "A veces", "Rara vez", "Nunca"], "answers_pt": ["Com frequência", "Às vezes", "Raramente", "Nunca"]}'::jsonb, 4),
('daily_trust_jealousy', '{"text_en": "What would damage your trust the most?", "text_tr": "Güvenini en çok ne zedeler?", "text_es": "¿Qué dañaría más tu confianza?", "text_pt": "O que mais abalaria sua confiança?"}'::jsonb, 'choice', true, '{"answers_en": ["A lie, even a small one", "Hidden conversations with someone", "A promise broken more than once", "Our private things shared with others"], "answers_tr": ["Küçük de olsa bir yalan", "Biriyle gizli konuşmalar", "Birden fazla kez tutulmayan bir söz", "Özelimizin başkalarıyla paylaşılması"], "answers_es": ["Una mentira, aunque sea pequeña", "Conversaciones ocultas con alguien", "Una promesa rota más de una vez", "Que se cuenten nuestras cosas privadas"], "answers_pt": ["Uma mentira, mesmo pequena", "Conversas escondidas com alguém", "Uma promessa quebrada mais de uma vez", "Nossas coisas íntimas contadas a outros"]}'::jsonb, 5),
('daily_trust_jealousy', '{"text_en": "How much do you want to know about each other''s day?", "text_tr": "Birbirinizin gününü ne kadar bilmek istersin?", "text_es": "¿Cuánto quieres saber del día del otro?", "text_pt": "Quanto você quer saber do dia um do outro?"}'::jsonb, 'choice', true, '{"answers_en": ["Everything, where and with whom", "The main things", "Only what they want to share"], "answers_tr": ["Her şeyi, nerede ve kiminle", "Önemli şeyleri", "Sadece paylaşmak istediklerini"], "answers_es": ["Todo, dónde y con quién", "Lo principal", "Solo lo que quiera contar"], "answers_pt": ["Tudo, onde e com quem", "O principal", "Só o que ele quiser contar"]}'::jsonb, 6),
('daily_trust_jealousy', '{"text_en": "What makes you feel completely secure with your partner?", "text_tr": "Partnerinle seni tamamen güvende hissettiren ne?", "text_es": "¿Qué te hace sentir completamente seguro/a con tu pareja?", "text_pt": "O que te faz se sentir totalmente seguro(a) com seu parceiro?"}'::jsonb, 'text', false, NULL, 7),
